using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.Json;
using Microsoft.ML.OnnxRuntime;
using OpenCvSharp;
using SkinDevApp.V6;
using Xunit;

namespace SkinDevApp.Tests
{
    /// <summary>
    /// Phase 3 tests of the V6 unified-assessment service. They check, against fixtures generated by the Python reference
    /// (v6/deployment/v6_test_vectors.json): the detector-evidence builder, the exported fusion ONNX files, calibration, flags and decisions;
    /// plus the safety rules (missing detector is not "no detection", Normal needs assessed quality, failures never look Normal) and the feature flag.
    /// C#-vs-Python tests on real photographs (Global scores, letterboxed detector coordinates) belong to Phase 5.
    /// </summary>
    [Collection("V6Flag")]
    public class V6Tests
    {
        private static string DeployDir => Path.Combine(AppContext.BaseDirectory, "v6deploy");

        private static string ModelDir()
        {
            string d = AppContext.BaseDirectory;
            while (d != null)
            {
                string p = Path.Combine(d, "v6", "astra_runs", "open_run02", "export");
                if (File.Exists(Path.Combine(p, "v6_global_features_mobilenetv2.onnx"))) return p;
                d = Path.GetDirectoryName(d);
            }
            throw new FileNotFoundException("V6 export folder (v6/astra_runs/open_run02/export) not found above " + AppContext.BaseDirectory);
        }

        private static V6Config Cfg() => V6Config.Load(Path.Combine(DeployDir, "v6_deployment_config.json"));

        private sealed class Vec
        {
            public string Name; public float[] Emb, GLogit, DetEv; public ConditionPool[] Pools;
            public double[] LogitsYolo, LogitsOnly, PYolo, POnly; public string[] Flags; public bool OodFlag;
            public string State; public string[] Decisions; public bool[] AbsenceSupported;
        }

        private static double[] D(JsonElement e) => e.EnumerateArray().Select(x => x.GetDouble()).ToArray();

        private static List<Vec> Vectors()
        {
            JsonElement root = JsonDocument.Parse(File.ReadAllText(Path.Combine(DeployDir, "v6_test_vectors.json"))).RootElement;
            var list = new List<Vec>();
            foreach (JsonElement v in root.GetProperty("vectors").EnumerateArray())
            {
                var pools = new ConditionPool[3];
                for (int j = 0; j < 3; j++)
                {
                    JsonElement b = v.GetProperty("boxes").GetProperty(V6Conditions.Names[j]);
                    var p = new ConditionPool { Condition = V6Conditions.Names[j], Available = b.ValueKind != JsonValueKind.Null };
                    if (p.Available)
                        foreach (JsonElement x in b.EnumerateArray())
                            p.Boxes.Add(new EvidenceBox { Conf = x.GetProperty("conf").GetDouble(), Deployed = x.GetProperty("deployed").GetBoolean(), RelArea = x.GetProperty("rel_area").GetDouble(), Cx = x.GetProperty("cx").GetDouble(), Cy = x.GetProperty("cy").GetDouble() });
                    pools[j] = p;
                }
                JsonElement ex = v.GetProperty("expected");
                list.Add(new Vec
                {
                    Name = v.GetProperty("name").GetString(), Emb = D(v.GetProperty("g_emb")).Select(x => (float)x).ToArray(), GLogit = D(v.GetProperty("g_logit")).Select(x => (float)x).ToArray(),
                    DetEv = D(v.GetProperty("det_ev")).Select(x => (float)x).ToArray(), Pools = pools,
                    LogitsYolo = D(v.GetProperty("fusion_global_yolo_logits")), LogitsOnly = D(v.GetProperty("fusion_global_only_logits")),
                    PYolo = D(v.GetProperty("calibrated_global_yolo")), POnly = D(v.GetProperty("calibrated_global_only")),
                    Flags = v.GetProperty("flags").EnumerateArray().Select(x => x.GetString()).ToArray(), OodFlag = v.GetProperty("ood_flag").GetBoolean(),
                    State = ex.GetProperty("state").GetString(),
                    Decisions = V6Conditions.Names.Select(n => ex.GetProperty("per_condition").GetProperty(n).GetProperty("decision").GetString()).ToArray(),
                    AbsenceSupported = V6Conditions.Names.Select(n => ex.GetProperty("per_condition").GetProperty(n).GetProperty("absence_supported").GetBoolean()).ToArray()
                });
            }
            return list;
        }

        private static ConditionPool Pool(string c, bool avail, params EvidenceBox[] boxes) { var p = new ConditionPool { Condition = c, Available = avail }; p.Boxes.AddRange(boxes); return p; }
        private static EvidenceBox Box(double conf, bool dep, double area = 0.01, double cx = 0.5, double cy = 0.5) => new EvidenceBox { Conf = conf, Deployed = dep, RelArea = area, Cx = cx, Cy = cy };
        private static ConditionPool[] Three(ConditionPool a, ConditionPool h, ConditionPool e) => new[] { a, h, e };
        private static string Name(ConditionStatus s) => s == ConditionStatus.Present ? "present" : s == ConditionStatus.Absent ? "absent" : "uncertain";

        // ------------------------------------------------------------------ evidence builder
        [Fact]
        public void Evidence_builder_reproduces_the_python_vector_for_every_fixture()
        {
            foreach (Vec v in Vectors())
            {
                float[] ev = DetectorEvidence.Build(v.Pools);
                Assert.Equal(21, ev.Length);
                for (int i = 0; i < 21; i++) Assert.True(Math.Abs(ev[i] - v.DetEv[i]) <= 1e-6, $"{v.Name}: det_ev[{i}] C# {ev[i]} vs Python {v.DetEv[i]}");
            }
        }

        [Fact]
        public void Detector_that_ran_without_boxes_is_available_with_no_detection()
        {
            float[] ev = DetectorEvidence.Build(Three(Pool("Acne", true), Pool("Hyperpigmentation", true), Pool("Eczema", true)));
            for (int j = 0; j < 3; j++) { Assert.Equal(1f, ev[j * 7]); for (int k = 1; k < 7; k++) Assert.Equal(0f, ev[j * 7 + k]); }
        }

        [Fact]
        public void Low_confidence_pool_boxes_are_seen_but_never_count_as_detected()
        {
            float[] ev = DetectorEvidence.Build(Three(Pool("Acne", true, Box(0.12, false), Box(0.20, false)), Pool("Hyperpigmentation", true), Pool("Eczema", true)));
            Assert.Equal(1f, ev[0]); Assert.Equal(0f, ev[1]); Assert.Equal(0f, ev[2]); Assert.Equal(0.20f, ev[3], 5);
            Assert.Equal(0f, ev[4]); Assert.Equal(0f, ev[5]); Assert.Equal(0f, ev[6]);
        }

        [Fact]
        public void Overlapping_boxes_use_the_best_deployed_box_and_no_box_count()
        {
            var one = DetectorEvidence.Build(Three(Pool("Acne", true, Box(0.64, true, 0.0100, 0.30, 0.60)), Pool("Hyperpigmentation", true), Pool("Eczema", true)));
            var many = DetectorEvidence.Build(Three(Pool("Acne", true, Box(0.64, true, 0.0100, 0.30, 0.60), Box(0.41, true, 0.0200, 0.31, 0.61), Box(0.30, true, 0.0300, 0.32, 0.62)), Pool("Hyperpigmentation", true), Pool("Eczema", true)));
            Assert.Equal(one, many);                                  // extra overlapping boxes do not change the evidence: no counts, only the best box
            Assert.Equal(0.64f, many[2], 5); Assert.Equal((float)Math.Sqrt(0.01), many[4], 5);
        }

        [Fact]
        public void Missing_detector_is_seven_zeros_including_available_zero_and_not_no_detection()
        {
            float[] ev = DetectorEvidence.Build(Three(Pool("Acne", true), Pool("Hyperpigmentation", false, Box(0.9, true)), Pool("Eczema", true)));   // boxes of an unavailable detector are ignored
            for (int k = 0; k < 7; k++) Assert.Equal(0f, ev[7 + k]);
            Assert.Equal(1f, ev[0]); Assert.Equal(1f, ev[14]);
        }

        [Fact]
        public void Multiple_conditions_fill_their_own_slots()
        {
            float[] ev = DetectorEvidence.Build(Three(Pool("Acne", true, Box(0.55, true)), Pool("Hyperpigmentation", true, Box(0.61, true)), Pool("Eczema", true, Box(0.47, true))));
            Assert.Equal(0.55f, ev[2], 5); Assert.Equal(0.61f, ev[9], 5); Assert.Equal(0.47f, ev[16], 5);
        }

        [Fact]
        public void Pixel_boxes_map_to_frame_fractions_and_respect_pool_minimum_and_deployed_threshold()
        {
            var boxes = new[] { new PixelBox { Conf = 0.80, X0 = 100, Y0 = 50, X1 = 200, Y1 = 150 }, new PixelBox { Conf = 0.10, X0 = 10, Y0 = 10, X1 = 30, Y1 = 30 }, new PixelBox { Conf = 0.03, X0 = 0, Y0 = 0, X1 = 5, Y1 = 5 } };
            ConditionPool p = DetectorEvidence.FromPixelBoxes("Hyperpigmentation", true, boxes, 400, 300, 0.225, 0.05, 60);
            Assert.Equal(2, p.Boxes.Count);                                              // 0.03 is below the 0.05 candidate-pool minimum
            EvidenceBox b = p.Boxes[0];
            Assert.Equal(0.375, b.Cx, 4); Assert.Equal(1.0 / 3.0, b.Cy, 4); Assert.Equal(10000.0 / 120000.0, b.RelArea, 6); Assert.True(b.Deployed);
            Assert.False(p.Boxes[1].Deployed);                                           // 0.10 < 0.225: pool only
            Assert.Equal(2, p.PixelBoxes.Count);
        }

        [Fact]
        public void Pixel_box_pool_is_capped_per_condition()
        {
            var many = Enumerable.Range(0, 100).Select(i => new PixelBox { Conf = 0.9 - i * 0.005, X0 = 1, Y0 = 1, X1 = 10, Y1 = 10 });
            Assert.Equal(60, DetectorEvidence.FromPixelBoxes("Acne", true, many, 100, 100, 0.275, 0.05, 60).Boxes.Count);
        }

        // ------------------------------------------------------------------ exported ONNX and calibration against the Python reference
        [Fact]
        public void Exported_fusion_models_reproduce_the_python_logits_on_cpu()
        {
            V6Config cfg = Cfg(); string dir = ModelDir();
            using (var sy = new InferenceSession(Path.Combine(dir, cfg.FusionGlobalYolo.File)))
            using (var so = new InferenceSession(Path.Combine(dir, cfg.FusionGlobalOnly.File)))
                foreach (Vec v in Vectors())
                {
                    double[] ly = V6Inference.RunFusion(sy, v.Emb, v.GLogit, v.DetEv), lo = V6Inference.RunFusion(so, v.Emb, v.GLogit, new float[21]);
                    for (int j = 0; j < 3; j++)
                    {
                        Assert.True(Math.Abs(ly[j] - v.LogitsYolo[j]) <= 1e-4, $"{v.Name}: global_yolo logit {j} C# {ly[j]} vs Python {v.LogitsYolo[j]}");
                        Assert.True(Math.Abs(lo[j] - v.LogitsOnly[j]) <= 1e-4, $"{v.Name}: global_only logit {j}");
                    }
                }
        }

        [Fact]
        public void Calibration_flags_and_decisions_reproduce_the_python_reference()
        {
            V6Config cfg = Cfg();
            foreach (Vec v in Vectors())
            {
                double[] py = V6Decision.ApplyPlatt(v.LogitsYolo, cfg.GlobalYolo.Platt), po = V6Decision.ApplyPlatt(v.LogitsOnly, cfg.GlobalOnly.Platt);
                for (int j = 0; j < 3; j++) { Assert.True(Math.Abs(py[j] - v.PYolo[j]) <= 1e-4, v.Name + ": calibrated global_yolo"); Assert.True(Math.Abs(po[j] - v.POnly[j]) <= 1e-4, v.Name + ": calibrated global_only"); }
                bool[] avail = Enumerable.Range(0, 3).Select(j => v.DetEv[j * 7] > 0.5f).ToArray(), detected = Enumerable.Range(0, 3).Select(j => v.DetEv[j * 7 + 1] > 0.5f).ToArray();
                List<string> flags = V6Decision.Flags(py, cfg.GlobalYolo.Thresholds, po, cfg.GlobalOnly.Thresholds, avail, detected, cfg.Band, v.OodFlag, QualityInput.Ok());
                Assert.Equal(v.Flags, flags);
                DecisionResult d = V6Decision.Decide(py, cfg.GlobalYolo.Thresholds, cfg.Band, avail, flags, v.OodFlag, QualityInput.Ok());
                Assert.Equal(v.State, d.State);
                for (int j = 0; j < 3; j++) { Assert.Equal(v.Decisions[j], Name(d.Status[j])); Assert.Equal(v.AbsenceSupported[j], d.AbsenceSupported[j]); }
            }
        }

        // ------------------------------------------------------------------ decision safety rules
        private static readonly double[] Thr = { 0.42, 0.37, 0.27 };
        private static DecisionResult Decide(double[] p, bool[] avail, IReadOnlyList<string> flags = null, bool ood = false, QualityInput q = null, string err = null)
            => V6Decision.Decide(p, Thr, 0.0, avail, flags ?? new string[0], ood, q ?? QualityInput.Ok(), err);

        [Fact]
        public void Normal_is_supported_only_when_every_condition_is_absent_with_a_working_detector_and_quality_ok()
        {
            Assert.Equal(V6States.NoFindingsSupported, Decide(new[] { 0.05, 0.05, 0.05 }, new[] { true, true, true }).State);
        }

        [Fact]
        public void Missing_detector_means_absence_is_not_supported_so_never_normal()
        {
            foreach (bool[] avail in new[] { new[] { true, true, false }, new[] { false, true, true }, new[] { false, false, false } })
            {
                DecisionResult d = Decide(new[] { 0.01, 0.01, 0.01 }, avail);
                Assert.Equal(V6States.UncertainReviewRequired, d.State);
                Assert.DoesNotContain(true, Enumerable.Range(0, 3).Where(j => !avail[j]).Select(j => d.AbsenceSupported[j]));
            }
        }

        [Fact]
        public void Normal_is_never_asserted_when_quality_was_not_assessed()
        {
            Assert.Equal(V6States.UncertainReviewRequired, Decide(new[] { 0.05, 0.05, 0.05 }, new[] { true, true, true }, q: QualityInput.NotAssessed()).State);
        }

        [Fact]
        public void Findings_states_and_review_precedence()
        {
            var all = new[] { true, true, true };
            Assert.Equal(V6States.FindingsSupported, Decide(new[] { 0.80, 0.05, 0.05 }, all).State);
            Assert.Equal(V6States.MultipleFindingsSupported, Decide(new[] { 0.80, 0.90, 0.05 }, all).State);
            Assert.Equal(V6States.UncertainReviewRequired, Decide(new[] { 0.80, 0.05, 0.05 }, all, new[] { "cnn_yolo_conflict_Acne" }).State);
            Assert.Equal(V6States.RecaptureRequired, Decide(new[] { 0.80, 0.05, 0.05 }, all, q: new QualityInput { Assessed = true, Blocking = { "blurry" } }).State);
            Assert.Equal(V6States.OutOfScopeReviewRequired, Decide(new[] { 0.80, 0.05, 0.05 }, all, ood: true).State);
            Assert.Equal(V6States.InferenceError, Decide(new[] { 0.80, 0.05, 0.05 }, all, err: "boom").State);
        }

        [Fact]
        public void Inference_errors_and_gates_never_look_normal_and_always_require_review()
        {
            var failed = UnifiedAssessment.Failed("boom");
            Assert.Equal(V6States.InferenceError, failed.State); Assert.False(failed.NormalSupported); Assert.True(failed.ReviewRequired);
            Assert.Equal(V6States.ReviewStatusPending, failed.ReviewStatus); Assert.True(failed.RequiresDermatologistReview); Assert.False(failed.ClinicalValidation);
        }

        [Fact]
        public void Conflict_flag_is_raised_only_when_the_detector_is_available()
        {
            double[] none = { 0.0, 0.0, 0.0 }, thrG = { 0.51, 0.39, 0.25 };
            List<string> f = V6Decision.Flags(new[] { 0.9, 0.9, 0.9 }, Thr, new[] { 0.9, 0.9, 0.9 }, thrG, new[] { true, true, false }, new[] { false, false, false }, 0.0, false, QualityInput.Ok());
            Assert.Equal(new[] { "cnn_yolo_conflict_Acne", "cnn_yolo_conflict_Hyperpigmentation" }, f);   // Eczema detector missing: no conflict can be claimed
        }

        [Fact]
        public void Global_logit_input_is_clipped_like_the_python_reference()
        {
            Assert.Equal(9.21f, V6Decision.GlobalLogitInput(50), 2); Assert.Equal(-9.21f, V6Decision.GlobalLogitInput(-50), 2);
            Assert.Equal(0.5f, V6Decision.GlobalLogitInput(0.5), 5);
        }

        // ------------------------------------------------------------------ configuration, flag, fail-closed loading
        [Fact]
        public void Feature_flag_is_off_by_default_and_a_broken_provider_never_turns_it_on()
        {
            Func<bool> keep = V6FeatureFlag.Provider; string env = Environment.GetEnvironmentVariable(V6FeatureFlag.EnvironmentVariable);
            try
            {
                V6FeatureFlag.Provider = null; Environment.SetEnvironmentVariable(V6FeatureFlag.EnvironmentVariable, null);
                Assert.False(V6FeatureFlag.IsEnabled);
                V6FeatureFlag.Provider = () => throw new InvalidOperationException("settings unreadable");
                Assert.False(V6FeatureFlag.IsEnabled);
                V6FeatureFlag.Provider = () => true; Assert.True(V6FeatureFlag.IsEnabled);
                V6FeatureFlag.Provider = null; Environment.SetEnvironmentVariable(V6FeatureFlag.EnvironmentVariable, "1"); Assert.True(V6FeatureFlag.IsEnabled);
            }
            finally { V6FeatureFlag.Provider = keep; Environment.SetEnvironmentVariable(V6FeatureFlag.EnvironmentVariable, env); }
        }

        [Fact]
        public void Config_matches_the_run_metadata_and_refuses_a_face_filtered_evidence_setting()
        {
            V6Config c = Cfg();
            Assert.Equal(new[] { 0.42, 0.37, 0.27 }, c.GlobalYolo.Thresholds); Assert.Equal(0.0, c.Band); Assert.Equal(new[] { 0.275, 0.225, 0.25 }, c.DeployedThresholds);
            Assert.Equal(0.02, c.MemberFloor); Assert.Equal(0.05, c.PoolMinConf); Assert.Equal(60, c.MaxBoxesPerCondition);
            string tmp = Path.Combine(Path.GetTempPath(), "v6cfg_" + Guid.NewGuid().ToString("N") + ".json");
            File.WriteAllText(tmp, File.ReadAllText(Path.Combine(DeployDir, "v6_deployment_config.json")).Replace("\"face_filter_for_evidence\": false", "\"face_filter_for_evidence\": true"));
            try { Assert.Throws<InvalidDataException>(() => V6Config.Load(tmp)); } finally { File.Delete(tmp); }
        }

        [Fact]
        public void Service_fails_closed_on_a_wrong_hash_and_on_a_missing_model()
        {
            string tmp = Path.Combine(Path.GetTempPath(), "v6dep_" + Guid.NewGuid().ToString("N")); Directory.CreateDirectory(tmp);
            try
            {
                File.Copy(Path.Combine(DeployDir, "v6_ood_model.json"), Path.Combine(tmp, "v6_ood_model.json"));
                string text = File.ReadAllText(Path.Combine(DeployDir, "v6_deployment_config.json")); V6Config c = Cfg();
                File.WriteAllText(Path.Combine(tmp, "v6_deployment_config.json"), text.Replace(c.GlobalFeatures.Sha256, new string('0', 64)));
                Assert.False(V6Inference.TryCreate(tmp, ModelDir(), new FakeSource(), out V6Inference s1, out string e1)); Assert.Null(s1); Assert.Contains("hash", e1);
                Assert.False(V6Inference.TryCreate(DeployDir, tmp, new FakeSource(), out V6Inference s2, out string e2)); Assert.Null(s2); Assert.Contains("not found", e2);
            }
            finally { Directory.Delete(tmp, true); }
        }

        // ------------------------------------------------------------------ end to end with the real exported models and a fake detector source
        private sealed class FakeSource : IDetectorSource
        {
            public Func<ConditionPool[]> Make = () => Three(Pool("Acne", false), Pool("Hyperpigmentation", false), Pool("Eczema", false));
            public ConditionPool[] Collect(Mat frameBgr, V6Config cfg) => Make();
        }

        private static Mat Frame()
        {
            var m = new Mat(300, 400, MatType.CV_8UC3);
            for (int y = 0; y < 300; y++) for (int x = 0; x < 400; x++) m.Set(y, x, new Vec3b((byte)((x * 3 + y) % 256), (byte)((x + y * 5) % 256), (byte)((x * 7 + y * 2) % 256)));
            return m;
        }

        [Fact]
        public void End_to_end_returns_one_structured_assessment_and_never_normal_without_detectors()
        {
            Assert.True(V6Inference.TryCreate(DeployDir, ModelDir(), new FakeSource(), out V6Inference svc, out string err), err);
            using (svc)
            using (Mat f = Frame())
            {
                UnifiedAssessment a = svc.Assess(f, QualityInput.Ok());
                Assert.NotEqual(V6States.InferenceError, a.State);
                Assert.Equal(3, a.Conditions.Length); Assert.Equal(new[] { "Acne", "Hyperpigmentation", "Eczema" }, a.Conditions.Select(c => c.Condition).ToArray());
                Assert.All(a.Conditions, c => { Assert.InRange(c.CalibratedProbability, 0.0, 1.0); Assert.False(c.DetectorAvailable); });
                Assert.False(a.NormalSupported);                                   // no detector coverage: absence can never be supported
                Assert.Equal(V6States.ReviewStatusPending, a.ReviewStatus); Assert.False(a.ClinicalValidation);
                Assert.Equal(400, a.FrameWidth); Assert.Equal(300, a.FrameHeight); Assert.Equal(3, a.ModelSha256.Count); Assert.Equal(Cfg().RunId, a.RunId);
                Assert.Contains(a.Reasons, r => r.Contains("detector unavailable"));
            }
        }

        [Fact]
        public void End_to_end_with_all_detectors_available_and_no_boxes_is_decided_by_the_fusion_only()
        {
            var src = new FakeSource { Make = () => Three(Pool("Acne", true), Pool("Hyperpigmentation", true), Pool("Eczema", true)) };
            Assert.True(V6Inference.TryCreate(DeployDir, ModelDir(), src, out V6Inference svc, out string err), err);
            using (svc) using (Mat f = Frame())
            {
                UnifiedAssessment a = svc.Assess(f, QualityInput.Ok());
                Assert.NotEqual(V6States.InferenceError, a.State);
                Assert.All(a.Conditions, c => { Assert.True(c.DetectorAvailable); Assert.False(c.DetectorFired); });
                Assert.Empty(a.Boxes);
            }
        }

        [Fact]
        public void End_to_end_failures_become_inference_error_not_normal()
        {
            var src = new FakeSource { Make = () => throw new InvalidOperationException("detector crashed") };
            Assert.True(V6Inference.TryCreate(DeployDir, ModelDir(), src, out V6Inference svc, out string err), err);
            using (svc)
            {
                UnifiedAssessment a = svc.Assess(null, QualityInput.Ok());
                Assert.Equal(V6States.InferenceError, a.State); Assert.False(a.NormalSupported); Assert.True(a.ReviewRequired);
                using (Mat f = Frame()) { UnifiedAssessment b = svc.Assess(f, QualityInput.Ok()); Assert.Equal(V6States.InferenceError, b.State); Assert.Contains("detector crashed", b.Error); }
            }
        }
    }
}
